pts=[(2,4),(2,15),(3,4),(4,4),(6,4),(6,15),(8,4),(9,4),(10,15),(12,15),(13,4),(17,4),(18,15),(19,4),(23,4),(23,5),(23,6),(23,7),(23,11)]
from collections import defaultdict
# connect any aligned with slope 0,inf,+-1
fills=set()
for i,(r,c) in enumerate(pts):
 for R,C in pts[i+1:]:
  dr,dc=R-r,C-c
  if dr==0 or dc==0 or abs(dr)==abs(dc):
   g=__import__('math').gcd(abs(dr),abs(dc))
   sr=dr//g if g else 0; sc=dc//g if g else 0
   # only cardinal/diagonal unit slope
   if (sr==0 or sc==0 or abs(sr)==abs(sc)):
    for k in range(1,g): fills.add((r+sr*k,c+sc*k))
len(fills),sorted(fills)[:20]
